/**
 * Pure parsers for the UMBRAL mission CSVs in data/processed/ (generated by scripts/).
 * No file-system access here: callers pass the file text, so this module is safe in any bundle.
 */
import type { CommStatus, CrewDayReading, CrewEvent, MissionDay, MissionPhase } from "./types";

export const MISSION_PHASES: readonly MissionPhase[] = ["transit_out", "mars_arrival", "surface", "mars_departure", "transit_return", "landed"];

/** RFC 4180-style CSV split: quoted fields may contain commas, newlines, and doubled quotes. */
export function parseCsv(text: string): string[][] {
  const rows: string[][] = [];
  let row: string[] = [];
  let field = "";
  let quoted = false;
  for (let index = 0; index < text.length; index += 1) {
    const char = text[index];
    if (quoted) {
      if (char === '"' && text[index + 1] === '"') {
        field += '"';
        index += 1;
      } else if (char === '"') {
        quoted = false;
      } else {
        field += char;
      }
    } else if (char === '"') {
      quoted = true;
    } else if (char === ",") {
      row.push(field);
      field = "";
    } else if (char === "\n" || char === "\r") {
      if (char === "\r" && text[index + 1] === "\n") index += 1;
      row.push(field);
      rows.push(row);
      row = [];
      field = "";
    } else {
      field += char;
    }
  }
  if (field !== "" || row.length > 0) {
    row.push(field);
    rows.push(row);
  }
  return rows.filter((cells) => cells.some((cell) => cell.trim() !== ""));
}

function records(text: string): Record<string, string>[] {
  const [header = [], ...rows] = parseCsv(text);
  const keys = header.map((key) => key.trim());
  return rows.map((cells) => Object.fromEntries(keys.map((key, index) => [key, (cells[index] ?? "").trim()])));
}

function toNumber(raw: string | undefined): number | null {
  if (raw === undefined || raw.trim() === "") return null;
  const value = Number(raw);
  return Number.isFinite(value) ? value : null;
}

function toDay(raw: string | undefined): number | null {
  const value = toNumber(raw);
  return value !== null && Number.isInteger(value) && value > 0 ? value : null;
}

/** "Inés" → "ines": lowercase ascii id used for routes and lookups. */
export function crewIdFromName(name: string): string {
  return name.trim().normalize("NFD").replace(/[̀-ͯ]/g, "").toLowerCase();
}

function toPhase(raw: string): MissionPhase {
  if ((MISSION_PHASES as readonly string[]).includes(raw)) return raw as MissionPhase;
  throw new Error("Unknown mission phase: " + raw);
}

function toComm(raw: string): CommStatus {
  return raw === "link" || raw === "blackout" ? raw : "unknown";
}

export function parseTimeline(text: string): MissionDay[] {
  return records(text).flatMap((row) => {
    const day = toDay(row.day);
    if (day === null) return [];
    return [{ day, date: row.date, phase: toPhase(row.phase), comm: toComm(row.comm) }];
  });
}

export function parseCrewDaily(text: string): CrewDayReading[] {
  return records(text).flatMap((row) => {
    const day = toDay(row.day);
    if (day === null || !row.crew) return [];
    return [
      {
        day,
        date: row.date,
        crewId: crewIdFromName(row.crew),
        heartRate: toNumber(row.hr_rest_bpm),
        systolic: toNumber(row.sbp_mmHg),
        diastolic: toNumber(row.dbp_mmHg),
        temperature: toNumber(row.temp_C),
        sleep: toNumber(row.sleep_h),
        mood: toNumber(row.mood_1to5),
        glucose: toNumber(row.glucose_mg_dL),
        radiation: toNumber(row.dose_cum_mSv),
        event: row.event ? row.event : null,
      },
    ];
  });
}

export function parseEvents(text: string): CrewEvent[] {
  return records(text).flatMap((row) => {
    const day = toDay(row.day);
    if (day === null || !row.crew || !row.event) return [];
    return [{ day, date: row.date, crewId: crewIdFromName(row.crew), event: row.event, detail: row.detail ?? "" }];
  });
}
